53	bool InternViTRunner::validateAndFillConfig(std::string const& engineDir)
54	{
55	    Json jsonConfig;
56	
57	    std::string configPath = engineDir + "/config.json";
58	    std::ifstream configFileStream(configPath);
59	    if (!configFileStream.is_open())
60	    {
61	        LOG_ERROR("Failed to open config file: %s", configPath.c_str());
62	        return false;
63	    }
64	
65	    try
66	    {
67	        jsonConfig = Json::parse(configFileStream);
68	        configFileStream.close();
69	    }
70	    catch (Json::parse_error const& e)
71	    {
72	        LOG_ERROR("Failed to parse config file with error: %s", e.what());
73	        return false;
74	    }
75	
76	    std::string modelTypeStr = jsonConfig["model_type"].get<std::string>();
77	    mModelType = multimodal::stringToModelType(modelTypeStr);
78	    if (mModelType != multimodal::ModelType::INTERNVL)
79	    {
80	        LOG_ERROR("Invalid model type: %s", modelTypeStr.c_str());
81	        return false;
82	    }
83	
84	    mConfig.imageTokenId = jsonConfig["image_token_id"].get<int32_t>();
85	    auto textConfig = jsonConfig["text_config"];
86	    mConfig.vocabSize = textConfig["vocab_size"].get<int32_t>();
87	
88	    auto visionConfig = jsonConfig["vision_config"];
89	    mConfig.numChannels = visionConfig["num_channels"].get<int64_t>();
90	    mConfig.patchSizeH = visionConfig["patch_size"][0].get<int64_t>();
91	    mConfig.patchSizeW = visionConfig["patch_size"][1].get<int64_t>();
92	    mConfig.blockImageSizeH = visionConfig["image_size"][0].get<int64_t>();
93	    mConfig.blockImageSizeW = visionConfig["image_size"][1].get<int64_t>();
94	
95	    auto builderConfig = jsonConfig["builder_config"];
96	    mConfig.minImageTokensPerImage = builderConfig["min_image_tokens"].get<int64_t>();
97	    mConfig.maxImageTokensPerImage = builderConfig["max_image_tokens_per_image"].get<int64_t>();
98	
99	    // Get config from engine shapes
100	    nvinfer1::Dims const inputShapeMax
101	        = mVisualEngine->getProfileShape(binding_names::kVisualInput, 0, nvinfer1::OptProfileSelector::kMAX);
102	    nvinfer1::Dims const inputShapeMin
103	        = mVisualEngine->getProfileShape(binding_names::kVisualInput, 0, nvinfer1::OptProfileSelector::kMIN);
104	    mConfig.maxNumBlocks = inputShapeMax.d[0];
105	    mConfig.minNumBlocks = inputShapeMin.d[0];
106	    mConfig.outHiddenSize = mVisualEngine->getTensorShape(binding_names::kVisualOutput).d[1];
107	
108	    return true;
