111	bool InternViTRunner::allocateBuffer(cudaStream_t stream)
112	{
113	    bool setTensorAddressStatus{true};
114	    LOG_INFO(
115	        "MConfig.maxNumBlocks: %d, mConfig.numChannels: %d, mConfig.blockImageSizeH: "
116	        "%d, mConfig.blockImageSizeW: %d",
117	        mConfig.maxNumBlocks, mConfig.numChannels, mConfig.blockImageSizeH, mConfig.blockImageSizeW);
118	    mVitInput
119	        = rt::Tensor({mConfig.maxNumBlocks, mConfig.numChannels, mConfig.blockImageSizeH, mConfig.blockImageSizeW},
120	            rt::DeviceType::kGPU, nvinfer1::DataType::kHALF, "InternViTRunner::mVitInput");
121	    setTensorAddressStatus &= mVisualContext->setTensorAddress(binding_names::kVisualInput, mVitInput.rawPointer());
122	    LOG_INFO("MConfig.maxNumBlocks: %d, mConfig.outHiddenSize: %d", mConfig.maxNumBlocks, mConfig.outHiddenSize);
123	    // In InternVL3, each block generates 256 tokens, so output size is maxNumBlocks*256
124	    mOutputEmbedding = rt::Tensor({mConfig.maxNumBlocks * 256, mConfig.outHiddenSize}, rt::DeviceType::kGPU,
125	        nvinfer1::DataType::kHALF, "InternViTRunner::mOutputEmbedding");
126	    setTensorAddressStatus
127	        &= mVisualContext->setTensorAddress(binding_names::kVisualOutput, mOutputEmbedding.rawPointer());
128	    if (!setTensorAddressStatus)
129	    {
130	        LOG_ERROR("Failed to set tensor address to the engine");
131	        return false;
132	    }
133	
134	    // Copy image mean and std to device to be used in normalizeImage
135	    int64_t const channels = static_cast<int64_t>(mConfig.imageMean.size());
136	    mImageMean
137	        = rt::Tensor({channels}, rt::DeviceType::kGPU, nvinfer1::DataType::kFLOAT, "InternViTRunner::mImageMean");
138	    mImageStd = rt::Tensor({channels}, rt::DeviceType::kGPU, nvinfer1::DataType::kFLOAT, "InternViTRunner::mImageStd");
139	    CUDA_CHECK(cudaMemcpyAsync(
140	        mImageMean.rawPointer(), mConfig.imageMean.data(), channels * sizeof(float), cudaMemcpyHostToDevice, stream));
141	    CUDA_CHECK(cudaMemcpyAsync(
142	        mImageStd.rawPointer(), mConfig.imageStd.data(), channels * sizeof(float), cudaMemcpyHostToDevice, stream));
143	
144	    // Pre-allocate temporary image buffers for preprocessing
145	    int64_t const maxImagePixels = mVitInput.getShape().volume();
146	    mImageDevice = rt::Tensor(
147	        {maxImagePixels}, rt::DeviceType::kGPU, nvinfer1::DataType::kUINT8, "InternViTRunner::mImageDevice");
148	    mNormalizedImageDevice = rt::Tensor(
149	        {maxImagePixels}, rt::DeviceType::kGPU, nvinfer1::DataType::kHALF, "InternViTRunner::mNormalizedImageDevice");
150	    // Scratch buffer for resizeImage output (4D placeholder shape; resizeImage reshapes per call).
151	    rt::Tensor resizeBuffer({1, 1, maxImagePixels, channels}, rt::DeviceType::kCPU, nvinfer1::DataType::kUINT8,
152	        "InternViTRunner::resizeBuffer");
153	    mResizedImageHost = rt::imageUtils::ImageData(std::move(resizeBuffer));
154	    // Thumbnail image has fixed size: 1 x blockImageSizeH x blockImageSizeW x channels (4D, frames=1).
155	    rt::Tensor thumbnailBuffer({1, mConfig.blockImageSizeH, mConfig.blockImageSizeW, channels}, rt::DeviceType::kCPU,
156	        nvinfer1::DataType::kUINT8, "InternViTRunner::thumbnailBuffer");
157	    mThumbnailImageHost = rt::imageUtils::ImageData(std::move(thumbnailBuffer));
158	
159	    return true;
160	}
161	
162	void InternViTRunner::formatPatch(imageUtils::ImageData const& image, std::vector<int64_t>& imageTokenLengths,
163	    int64_t& numImages, int64_t& totalNumBlocks, bool isThumbnail, cudaStream_t stream)
164	{
165	    int64_t height = image.height;
166	    int64_t width = image.width;
167	    int64_t channels = image.channels;
168	    unsigned char* imageData = image.data(); // In hwc order
169	
170	    ELLM_CHECK(channels == mConfig.numChannels,
171	        "Image channels mismatch, got " + std::to_string(channels) + ", expected "
172	            + std::to_string(mConfig.numChannels));
173	    ELLM_CHECK(height % mConfig.blockImageSizeH == 0 && width % mConfig.blockImageSizeW == 0,
174	        "Image height or width is not divisible by blockImageSizeH or blockImageSizeW, "
175	        "got height: "
176	            + std::to_string(height) + ", width: " + std::to_string(width)
177	            + ", blockImageSizeH: " + std::to_string(mConfig.blockImageSizeH)
178	            + ", blockImageSizeW: " + std::to_string(mConfig.blockImageSizeW));
179	
180	    int64_t curNumBlocks = (height / mConfig.blockImageSizeH) * (width / mConfig.blockImageSizeW);
181	    ELLM_CHECK(totalNumBlocks + curNumBlocks <= mConfig.maxNumBlocks,
182	        "totalNumBlocks " + std::to_string(totalNumBlocks) + " + curNumBlocks " + std::to_string(curNumBlocks)
183	            + " exceeds the limitation, max = " + std::to_string(mConfig.maxNumBlocks) + " of VIT engine.");
184	
185	    int64_t curTokenLength = curNumBlocks * 256;
186	    if (isThumbnail)
187	    {
188	        // Add to the last image token length, instead of considered as a new image
189	        imageTokenLengths.back() += curTokenLength;
190	    }
191	    else
192	    {
193	        imageTokenLengths.push_back(curTokenLength);
194	        ++numImages;
195	    }
196	
197	    // Reshape pre-allocated temporary buffers to current image dimensions
198	    check::check(mImageDevice.reshape({1, height, width, channels}), "Tensor reshape failed");
199	    check::check(mNormalizedImageDevice.reshape({1, height, width, channels}), "Tensor reshape failed");
200	
201	    // Copy image to device
202	    CUDA_CHECK(cudaMemcpyAsync(
203	        mImageDevice.rawPointer(), imageData, height * width * channels, cudaMemcpyHostToDevice, stream));
204	
205	    // Normalize image
206	    kernel::normalizeImage(mImageDevice, mImageMean, mImageStd, mNormalizedImageDevice, stream);
207	
208	    // Transpose to patch
209	    int64_t offset = totalNumBlocks * mConfig.numChannels * mConfig.blockImageSizeH * mConfig.blockImageSizeW;
210	    kernel::transposeToPatchInternVLPhi4MM(mNormalizedImageDevice, mVitInput, offset, stream);
211	
212	    // Update numBlocks
213	    totalNumBlocks += curNumBlocks;
214	}
215	
216	void InternViTRunner::imagePreprocess(rt::LLMGenerationRequest const& request, std::vector<int64_t>& imageTokenLengths,
217	    std::vector<int64_t>& numImages, bool doResize, cudaStream_t stream)
218	{
219	    int64_t totalNumBlocks = 0;
220	
221	    for (auto const& req : request.requests)
222	    {
223	        int64_t numImage = 0;
224	        for (auto const& image : req.imageBuffers)
225	        {
226	            int64_t const blocksBeforePatch = totalNumBlocks;
227	            if (doResize)
228	            {
229	                auto [resizedHeight, resizedWidth] = imageUtils::computeBestBlockGridForResize(image.height,
230	                    image.width, mConfig.minImageTokensPerImage, mConfig.maxImageTokensPerImage,
231	                    mConfig.blockImageSizeH, mConfig.blockImageSizeW);
232	                rt::imageUtils::resizeImage(
233	                    image, mResizedImageHost, resizedWidth, resizedHeight, rt::imageUtils::InterpolationMode::kBICUBIC);
234	                formatPatch(mResizedImageHost, imageTokenLengths, numImage, totalNumBlocks, false, stream);
235	            }
236	            else
237	            {
238	                formatPatch(image, imageTokenLengths, numImage, totalNumBlocks, false, stream);
239	            }
240	            // Add a thumbnail tile when (a) the image has more than 1 main block (matches
241	            // HuggingFace behavior) or (b) the engine's MIN-profile demands more than 1 block
242	            // (engines built with `visual_build --minImageTokens > 256`). Without (b), a
243	            // single-block image would invoke the engine with totalNumBlocks=1 and the
244	            // optimization profile would reject it at runtime.
245	            int64_t const mainImageBlocks = totalNumBlocks - blocksBeforePatch;
246	            if (mainImageBlocks > 1 || mConfig.minNumBlocks > 1)
247	            {
248	                rt::imageUtils::resizeImage(image, mThumbnailImageHost, mConfig.blockImageSizeW,
249	                    mConfig.blockImageSizeH, rt::imageUtils::InterpolationMode::kBICUBIC);
250	                formatPatch(mThumbnailImageHost, imageTokenLengths, numImage, totalNumBlocks, true, stream);
251	            }
252	        }
253	        numImages.emplace_back(numImage);
254	    }
255	
256	    if (totalNumBlocks == 0)
257	    {
258	        check::check(
259	            mVitInput.reshape({totalNumBlocks, mConfig.numChannels, mConfig.blockImageSizeH, mConfig.blockImageSizeW}),
260	            "Tensor reshape failed");
261	        return;
262	    }
263	
264	    ELLM_CHECK(totalNumBlocks >= mConfig.minNumBlocks && totalNumBlocks <= mConfig.maxNumBlocks,
265	        "totalNumBlocks " + std::to_string(totalNumBlocks)
266	            + " exceeds the limitation, max = " + std::to_string(mConfig.maxNumBlocks)
267	            + ", min = " + std::to_string(mConfig.minNumBlocks) + " of VIT engine.");
268	
269	    // Calculate total image tokens for profiling (InternVL: each block generates 256 tokens)
270	    int64_t totalImageTokens = totalNumBlocks * 256;
271	
272	    // Record performance data
273	    int64_t imageCount = std::accumulate(numImages.begin(), numImages.end(), int64_t(0));
274	    mMultimodalMetrics.recordRun(imageCount, totalImageTokens);
275	
276	    check::check(
277	        mVitInput.reshape({totalNumBlocks, mConfig.numChannels, mConfig.blockImageSizeH, mConfig.blockImageSizeW}),
278	        "Tensor reshape failed");
279	    check::check(mOutputEmbedding.reshape({totalImageTokens, mConfig.outHiddenSize}), "Tensor reshape failed");
280	}
281	
282	void InternViTRunner::textPreprocess(rt::LLMGenerationRequest const& request,
283	    std::vector<std::vector<int32_t>>& batchInputIds, std::vector<int64_t> const& numImages,
284	    std::vector<int64_t> const& imageTokenLengths, trt_edgellm::tokenizer::Tokenizer const* tokenizer)
285	{
286	    if (numImages.size() != request.requests.size())
287	    {
288	        std::string errorMsg = "InternViTRunner::textPreprocess() numImages.size() != request.requests.size(), "
289	            + std::to_string(numImages.size()) + " != " + std::to_string(request.requests.size());
290	        LOG_ERROR("%s", errorMsg.c_str());
291	        throw std::runtime_error(errorMsg);
292	    }
293	
294	    int64_t imageIndex = 0;
295	    // Image token id will start from vocabSize and increment for each image token position
296	    int32_t imageTokenId = mConfig.vocabSize;
297	
298	    for (size_t i = 0; i < request.requests.size(); ++i)
299	    {
300	        // Use the formatted complete request
301	        std::vector<int32_t> ids = tokenizer->encode(request.formattedRequests[i].formattedCompleteRequest);
302	        check::check(!ids.empty(), "InternViTRunner::textPreprocess() Failed to encode text");
303	
304	        // replace vis tokens
305	        std::vector<int32_t> newIds;
306	        for (size_t j = 0; j < ids.size(); ++j)
307	        {
308	            if (ids[j] == mConfig.imageTokenId)
309	            {
310	                // Prepend <img> token
311	                newIds.push_back(mConfig.imgStartTokenId);
312	
313	                int64_t numImageTokens = imageTokenLengths.at(imageIndex);
314	                for (int64_t k = 0; k < numImageTokens; ++k)
315	                {
316	                    newIds.push_back(imageTokenId);
317	                    ++imageTokenId;
318	                }
319	
320	                // Append </img> token
321	                newIds.push_back(mConfig.imgEndTokenId);
322	                ++imageIndex;
323	            }
324	            else
325	            {
326	                newIds.push_back(ids[j]);
327	            }
328	        }
329	        batchInputIds.emplace_back(std::move(newIds));
330	    }
331	}
332	
333	bool InternViTRunner::preprocess(rt::LLMGenerationRequest const& request,
334	    std::vector<std::vector<int32_t>>& batchedInputIds, tokenizer::Tokenizer const* tokenizer,
335	    [[maybe_unused]] rt::OptionalOutputTensor mropeCosSinOut, cudaStream_t stream, bool imageOnly) noexcept
336	{
337	    std::vector<int64_t> imageTokenLengths;
338	    std::vector<int64_t> numImages;
339	
340	    try
341	    {
342	        imagePreprocess(request, imageTokenLengths, numImages, !imageOnly, stream);
343	        if (!imageOnly)
344	        {
345	            textPreprocess(request, batchedInputIds, numImages, imageTokenLengths, tokenizer);
346	        }
347	    }
348	    catch (std::exception const& e)
349	    {
350	        LOG_ERROR("Failed: %s", e.what());
351	        return false;
352	    }
353	
354	    return true;
355	}
356	
357	bool InternViTRunner::infer(cudaStream_t stream) noexcept
358	{
359	    // Skip VIT inference if there are no images to process
360	    // Check if the first dimension (sequence length) is 0, indicating no images
361	    if (mVitInput.getShape()[0] == 0)
362	    {
363	        return true;
364	    }
365	
366	    // Profile ViT inference with automatic cleanup
367	    {
368	        TIME_STAGE(metrics::StageNames::kMULTIMODAL_PROCESSING, stream);
369	
370	        bool setEngineIOStatus{true};
371	        setEngineIOStatus
372	            &= mVisualContext->setInputShape(binding_names::kVisualInput, mVitInput.getShape().getTRTDims());
373	        if (!setEngineIOStatus)
374	        {
375	            LOG_ERROR("Failed to bind engine input tensors.");
376	            return false;
377	        }
378	
379	        bool enqueueStatus = mVisualContext->enqueueV3(stream);
380	        if (!enqueueStatus)
381	        {
382	            LOG_ERROR("Failed to enqueue engine.");
383	            return false;
384	        }
385	    }
386	
387	    return true;
388	}
389	
390	} // namespace rt
391	} // namespace trt_edgellm
