65	bool QwenViTRunner::validateAndFillConfig(std::string const& engineDir)
66	{
67	    Json jsonConfig;
68	
69	    std::string configPath = engineDir + "/config.json";
70	    std::ifstream configFileStream(configPath);
71	    if (!configFileStream.is_open())
72	    {
73	        LOG_ERROR("Failed to open config file: %s", configPath.c_str());
74	        return false;
75	    }
76	
77	    try
78	    {
79	        jsonConfig = Json::parse(configFileStream);
80	        configFileStream.close();
81	    }
82	    catch (Json::parse_error const& e)
83	    {
84	        LOG_ERROR("Failed to parse config file with error: %s", e.what());
85	        return false;
86	    }
87	
88	    std::string modelTypeStr = jsonConfig["model_type"].get<std::string>();
89	    mModelType = multimodal::stringToModelType(modelTypeStr);
90	    if (mModelType != multimodal::ModelType::QWEN2_5_VL && mModelType != multimodal::ModelType::QWEN2_VL
91	        && mModelType != multimodal::ModelType::QWEN3_VL && mModelType != multimodal::ModelType::QWEN3_5
92	        && mModelType != multimodal::ModelType::QWEN3_OMNI_VISION_ENCODER)
93	    {
94	        LOG_ERROR("Invalid model type: %s", modelTypeStr.c_str());
95	        return false;
96	    }
97	
98	    mConfig.visionStartTokenId = jsonConfig["vision_start_token_id"].get<int32_t>();
99	    mConfig.visionEndTokenId = jsonConfig.value("vision_end_token_id", 0);
100	    mConfig.imageTokenId = jsonConfig["image_token_id"].get<int32_t>();
101	    mConfig.videoTokenId = jsonConfig["video_token_id"].get<int32_t>();
102	
103	    auto const& subConfig = (jsonConfig.contains("text_config") && jsonConfig["text_config"].is_object())
104	        ? jsonConfig["text_config"]
105	        : jsonConfig;
106	    mConfig.vocabSize = subConfig["vocab_size"].get<int32_t>();
107	    mConfig.mropeTheta = subConfig["rope_theta"].get<float>();
108	
109	    // Read mrope_section from rope_parameters or rope_scaling
110	    auto const& ropeParams = subConfig.contains("rope_scaling") ? subConfig["rope_scaling"] : subConfig;
111	    if (ropeParams.contains("mrope_section"))
112	    {
113	        auto section = ropeParams["mrope_section"].get<std::vector<int32_t>>();
114	        if (section.size() >= 3)
115	        {
116	            mConfig.mropeSectionH = section[1];
117	            mConfig.mropeSectionW = section[2];
118	        }
119	    }
120	    if (mConfig.mropeSectionH <= 0 || mConfig.mropeSectionW <= 0)
121	    {
122	        LOG_ERROR("Failed to parse mrope_section in text_config. Got H=%d, W=%d", mConfig.mropeSectionH,
123	            mConfig.mropeSectionW);
124	        return false;
125	    }
126	
127	    if (!validateExtraConfig(jsonConfig))
128	    {
129	        return false;
130	    }
131	
132	    auto builderConfig = jsonConfig["builder_config"];
133	    mConfig.minImageTokensPerImage = builderConfig["min_image_tokens"].get<int64_t>();
134	    mConfig.maxImageTokensPerImage = builderConfig["max_image_tokens_per_image"].get<int64_t>();
135	    mUseTrtNativeVitAttn = builderConfig.value("use_trt_native_vit_attn", false);
136	    if (mConfig.minImageTokensPerImage <= 0 || mConfig.maxImageTokensPerImage <= 0)
137	    {
138	        LOG_ERROR(
139	            "minImageTokensPerImage and maxImageTokensPerImage must be "
140	            "positive, got %d and %d",
141	            mConfig.minImageTokensPerImage, mConfig.maxImageTokensPerImage);
142	        return false;
143	    }
144	
145	    // Get preprocessor config
146	    Json preprocessorConfig;
147	    std::string preprocessorConfigPath = engineDir + "/preprocessor_config.json";
148	    std::ifstream preprocessorConfigFileStream(preprocessorConfigPath);
149	    if (!preprocessorConfigFileStream.is_open())
150	    {
151	        LOG_ERROR("Failed to open preprocessor config file: %s", preprocessorConfigPath.c_str());
152	        return false;
153	    }
154	    try
155	    {
156	        preprocessorConfig = Json::parse(preprocessorConfigFileStream);
157	        preprocessorConfigFileStream.close();
158	    }
159	    catch (Json::parse_error const& e)
160	    {
161	        LOG_ERROR("Failed to parse preprocessor config file with error: %s", e.what());
162	        return false;
163	    }
164	
165	    auto const& imageProcessorConfig
166	        = (preprocessorConfig.contains("image_processor") && preprocessorConfig["image_processor"].is_object())
167	        ? preprocessorConfig["image_processor"]
168	        : preprocessorConfig;
169	    mConfig.patchSize = imageProcessorConfig["patch_size"].get<int64_t>();
170	    mConfig.temporalPatchSize = imageProcessorConfig["temporal_patch_size"].get<int64_t>();
171	    mConfig.mergeSize = imageProcessorConfig["merge_size"].get<int64_t>();
172	    mConfig.imageMean = imageProcessorConfig["image_mean"].get<std::vector<float>>();
173	    mConfig.imageStd = imageProcessorConfig["image_std"].get<std::vector<float>>();
174	
175	    // Get config from engine shapes
176	    nvinfer1::Dims const inputShapeMax
177	        = mVisualEngine->getProfileShape(binding_names::kVisualInput, 0, nvinfer1::OptProfileSelector::kMAX);
178	    nvinfer1::Dims const inputShapeMin
179	        = mVisualEngine->getProfileShape(binding_names::kVisualInput, 0, nvinfer1::OptProfileSelector::kMIN);
180	    mConfig.maxHW = inputShapeMax.d[0];
181	    mConfig.minHW = inputShapeMin.d[0];
182	    auto maxImageTokens = mConfig.maxHW / (mConfig.mergeSize * mConfig.mergeSize);
183	    // Mirrors the visual engine's cu_seqlens profile max (maxImageTokens / minImageTokens). For video this also
184	    // bounds the number of per-frame cu_seqlens entries (one per frame block), not just the image count.
185	    mConfig.maxNumImages = maxImageTokens / mConfig.minImageTokensPerImage;
186	    mConfig.inputDim = mVisualContext->getTensorShape(binding_names::kVisualInput).d[1];
187	    mConfig.vitPosEmbDim = mVisualContext->getTensorShape(binding_names::kRotaryPosEmb).d[1];
188	    mConfig.outHiddenSize = mVisualEngine->getTensorShape(binding_names::kVisualOutput).d[1];
189	
190	    return true;
191	}
