193	bool QwenViTRunner::allocateBuffer(cudaStream_t stream)
194	{
195	    bool setTensorAddressStatus{true};
196	    mVitInput = rt::Tensor(
197	        {mConfig.maxHW, mConfig.inputDim}, rt::DeviceType::kGPU, nvinfer1::DataType::kHALF, "QwenViTRunner::mVitInput");
198	    setTensorAddressStatus &= mVisualContext->setTensorAddress(binding_names::kVisualInput, mVitInput.rawPointer());
199	
200	    mRotaryPosEmb = rt::Tensor({mConfig.maxHW, mConfig.vitPosEmbDim}, rt::DeviceType::kGPU, nvinfer1::DataType::kFLOAT,
201	        "QwenViTRunner::mRotaryPosEmb");
202	    setTensorAddressStatus
203	        &= mVisualContext->setTensorAddress(binding_names::kRotaryPosEmb, mRotaryPosEmb.rawPointer());
204	
205	    // The size of the tensor is maxNumImages + 1 because the first element is 0.
206	    mCuSeqlens = rt::Tensor(
207	        {mConfig.maxNumImages + 1}, rt::DeviceType::kGPU, nvinfer1::DataType::kINT32, "QwenViTRunner::mCuSeqlens");
208	    setTensorAddressStatus &= mVisualContext->setTensorAddress(binding_names::kCuSeqlens, mCuSeqlens.rawPointer());
209	    // Pre-allocate host tensor for cumulative sequence lengths.
210	    mCuSeqlensHost = rt::Tensor(
211	        {mConfig.maxNumImages + 1}, rt::DeviceType::kCPU, nvinfer1::DataType::kINT32, "QwenViTRunner::mCuSeqlensHost");
212	
213	    // kv_lengths is required when using TRT-native attention (TRT >= 11).
214	    // TRT IAttentionV2 requires query_lengths and kv_lengths to be distinct tensors,
215	    // so we allocate a separate buffer and copy the same cu_seqlens data at runtime.
216	    if (mUseTrtNativeVitAttn)
217	    {
218	        bool const hasKvLengths = isEngineInput(*mVisualEngine, binding_names::kKvLengths);
219	        if (!hasKvLengths)
220	        {
221	            LOG_ERROR("Config has use_trt_native_vit_attn=true but engine is missing kv_lengths binding");
222	            return false;
223	        }
224	        mKvLengths = rt::Tensor(
225	            {mConfig.maxNumImages + 1}, rt::DeviceType::kGPU, nvinfer1::DataType::kINT32, "QwenViTRunner::mKvLengths");
226	        setTensorAddressStatus &= mVisualContext->setTensorAddress(binding_names::kKvLengths, mKvLengths.rawPointer());
227	    }
228	
229	    mHasMaxSeqLenCarrier = isEngineInput(*mVisualEngine, binding_names::kMaxSeqLenCarrier);
230	    if (mHasMaxSeqLenCarrier)
231	    {
232	        mMaxSeqLenCarrier = rt::Tensor(
233	            {mConfig.maxHW}, rt::DeviceType::kGPU, nvinfer1::DataType::kINT32, "QwenViTRunner::mMaxSeqLenCarrier");
234	        setTensorAddressStatus
235	            &= mVisualContext->setTensorAddress(binding_names::kMaxSeqLenCarrier, mMaxSeqLenCarrier.rawPointer());
236	    }
237	
238	    // In Qwen-VL, VIT input mHW is always numImageTokens * spatial_merge_size ** 2.
239	    auto const maxImageTokens = mConfig.maxHW / (mConfig.mergeSize * mConfig.mergeSize);
240	    mOutputEmbedding = rt::Tensor({maxImageTokens, mConfig.outHiddenSize}, rt::DeviceType::kGPU,
241	        nvinfer1::DataType::kHALF, "QwenViTRunner::mOutputEmbedding");
242	    setTensorAddressStatus
243	        &= mVisualContext->setTensorAddress(binding_names::kVisualOutput, mOutputEmbedding.rawPointer());
244	
245	    // Allocate model-specific ViT-input buffers
246	    setTensorAddressStatus &= allocateExtraBuffers(maxImageTokens);
247	
248	    if (!setTensorAddressStatus)
249	    {
250	        LOG_ERROR("Failed to set tensor address to the engine");
251	        return false;
252	    }
253	
254	    // Copy image mean and std to device to be used in normalizeImage
255	    auto nbBytes = mConfig.imageMean.size() * sizeof(float);
256	    auto channels = math::cast<int64_t>(mConfig.imageMean.size());
257	    mImageMean = rt::Tensor({channels}, rt::DeviceType::kGPU, nvinfer1::DataType::kFLOAT, "QwenViTRunner::mImageMean");
258	    mImageStd = rt::Tensor({channels}, rt::DeviceType::kGPU, nvinfer1::DataType::kFLOAT, "QwenViTRunner::mImageStd");
259	    CUDA_CHECK(
260	        cudaMemcpyAsync(mImageMean.rawPointer(), mConfig.imageMean.data(), nbBytes, cudaMemcpyHostToDevice, stream));
261	    CUDA_CHECK(
262	        cudaMemcpyAsync(mImageStd.rawPointer(), mConfig.imageStd.data(), nbBytes, cudaMemcpyHostToDevice, stream));
263	
264	    // Pre-allocate temporary image buffers for preprocessing
265	    int64_t const maxImagePixels = mVitInput.getShape().volume();
266	    // Scratch buffer for resizeImage output. Initial shape is a placeholder; resizeImage reshapes to
267	    // [T, realH, realW, channels] per call. Lead 1s keep the 4D layout ImageData enforces.
268	    rt::Tensor resizeBuffer({1, 1, maxImagePixels, channels}, rt::DeviceType::kCPU, nvinfer1::DataType::kUINT8,
269	        "QwenViTRunner::resizeBuffer");
270	    mResizedImageHost = rt::imageUtils::ImageData(std::move(resizeBuffer));
271	    mImageDevice
272	        = rt::Tensor({maxImagePixels}, rt::DeviceType::kGPU, nvinfer1::DataType::kUINT8, "QwenViTRunner::mImageDevice");
273	    mNormalizedImageDevice = rt::Tensor(
274	        {maxImagePixels}, rt::DeviceType::kGPU, nvinfer1::DataType::kHALF, "QwenViTRunner::mNormalizedImageDevice");
275	
276	    // Pre-allocate tensors for MRoPE position IDs
277	    mMropePositionIdsHost = rt::Tensor({mLLMMaxBatchSize, 3, mLLMMaxSequenceLength}, rt::DeviceType::kCPU,
278	        nvinfer1::DataType::kINT64, "QwenViTRunner::mMropePositionIdsHost");
279	    mMropePositionIdsDevice = rt::Tensor({mLLMMaxBatchSize, 3, mLLMMaxSequenceLength}, rt::DeviceType::kGPU,
280	        nvinfer1::DataType::kINT64, "QwenViTRunner::mMropePositionIdsDevice");
281	
282	    return true;
283	}
284	
285	std::tuple<int64_t, int64_t> QwenViTRunner::computeVisionSpans(
286	    rt::imageUtils::ImageData const& image, int64_t patchBase, std::vector<VisionSpan>& spans)
287	{
288	    int64_t const height = image.height;
289	    int64_t const width = image.width;
290	
291	    ELLM_CHECK(
292	        height % (mConfig.patchSize * mConfig.mergeSize) == 0 && width % (mConfig.patchSize * mConfig.mergeSize) == 0,
293	        "Image height or width is not divisible by patchSize * mergeSize = "
294	            + std::to_string(mConfig.patchSize * mConfig.mergeSize) + " got height: " + std::to_string(height)
295	            + ", width: " + std::to_string(width));
296	
297	    // gridT = ceil(srcFrames / temporalPatchSize) (HF pads T up to a multiple of temporalPatchSize; image -> 1).
298	    int64_t const gridT = (image.frames + mConfig.temporalPatchSize - 1) / mConfig.temporalPatchSize;
299	    int64_t const gridH = height / mConfig.patchSize;   // HF grid_h (patch units)
300	    int64_t const gridW = width / mConfig.patchSize;    // HF grid_w (patch units)
301	    int64_t const llmGridH = gridH / mConfig.mergeSize; // HF llm_grid_h
302	    int64_t const llmGridW = gridW / mConfig.mergeSize; // HF llm_grid_w
303	    int64_t const tokensPerFrame = llmGridH * llmGridW;
304	
305	    // Base = one flat span.
306	    VisionSpan span;
307	    span.vit = VitFrameGrid{gridT, gridH, gridW, patchBase};
308	    span.llm = LlmVisionBlock{gridT * tokensPerFrame, /*llmGridT*/ gridT, llmGridH, llmGridW};
309	    spans.push_back(span);
310	    return {/*totalSeqLen*/ gridT * gridH * gridW, /*totalGridT*/ gridT};
311	}
312	
313	void QwenViTRunner::formatPatch(
314	    rt::imageUtils::ImageData const& image, std::vector<VisionSpan>& spans, int64_t& patchBase, cudaStream_t stream)
315	{
316	    int64_t const height = image.height;
317	    int64_t const width = image.width;
318	    int64_t const channels = image.channels;
319	    unsigned char* imageData = image.data(); // THWC order
320	
321	    // computeVisionSpans (the one model-aware step) appends this buffer's spans starting at the running patch offset.
322	    int64_t const prevPatchBase = patchBase;
323	    auto const [totalSeqLen, totalGridT] = computeVisionSpans(image, prevPatchBase, spans);
324	
325	    ELLM_CHECK(prevPatchBase + totalSeqLen <= mConfig.maxHW,
326	        "Visual token count " + std::to_string(prevPatchBase + totalSeqLen)
327	            + " exceeds the ViT engine budget maxHW = " + std::to_string(mConfig.maxHW)
328	            + " (for video this grows with frame count; rebuild the visual engine with a larger --maxImageTokens).");
329	    patchBase += totalSeqLen;
330	
331	    // Physical frames consumed = grid_t groups * temporalPatchSize (HF pads T to a multiple of temporalPatchSize).
332	    int64_t const nSourceFrames = image.frames;
333	    int64_t const tPadded = totalGridT * mConfig.temporalPatchSize;
334	
335	    // Reshape pre-allocated temporary buffers to current image dimensions
336	    check::check(mImageDevice.reshape({tPadded, height, width, channels}), "Tensor reshape failed");
337	    check::check(mNormalizedImageDevice.reshape({tPadded, height, width, channels}), "Tensor reshape failed");
338	
339	    // Copy the source frames in one transfer, then replicate the last frame into any padded slots.
340	    int64_t const frameBytes = height * width * channels;
341	    CUDA_CHECK(cudaMemcpyAsync(
342	        mImageDevice.rawPointer(), imageData, nSourceFrames * frameBytes, cudaMemcpyHostToDevice, stream));
343	    unsigned char const* lastFrameSrc = imageData + (nSourceFrames - 1) * frameBytes;
344	    for (int64_t i = nSourceFrames; i < tPadded; ++i)
345	    {
346	        CUDA_CHECK(cudaMemcpyAsync(static_cast<std::byte*>(mImageDevice.rawPointer()) + i * frameBytes, lastFrameSrc,
347	            frameBytes, cudaMemcpyHostToDevice, stream));
348	    }
349	
350	    // Normalize image
351	    kernel::normalizeImage(mImageDevice, mImageMean, mImageStd, mNormalizedImageDevice, stream);
352	
353	    // Transpose to patch
354	    kernel::transposeToPatchQwenViT(mNormalizedImageDevice, mVitInput, prevPatchBase * mConfig.inputDim,
355	        mConfig.temporalPatchSize, mConfig.patchSize, mConfig.mergeSize, stream);
356	}
357	
358	void QwenViTRunner::buildCuSeqlens(
359	    std::vector<VisionSpan> const& spans, int32_t* cuSeqlensData, int64_t& cuSeqlensSize, int64_t& maxSeqLen) const
360	{
361	    // Per-frame cu_seqlens (HF get_vision_cu_seqlens = repeat_interleave(H*W, gridT)): each span expands into its
362	    // gridT per-frame gridH*gridW blocks.
363	    int64_t const cuSeqlensCapacity = mCuSeqlensHost.getShape().volume(); // maxNumImages + 1 entries
364	    cuSeqlensData[0] = 0;
365	    cuSeqlensSize = 1;
366	    maxSeqLen = 0;
367	    int64_t runningCuSeqlen = 0;
368	    for (auto const& s : spans)
369	    {
370	        auto const& g = s.vit;
371	        int64_t const blockSeqLen = g.gridH * g.gridW;
372	        for (int64_t t = 0; t < g.gridT; ++t)
373	        {
374	            ELLM_CHECK(cuSeqlensSize < cuSeqlensCapacity,
375	                "cuSeqlens frame count exceeds buffer capacity " + std::to_string(cuSeqlensCapacity)
376	                    + " (maxNumImages = " + std::to_string(mConfig.maxNumImages) + ") of VIT engine.");
377	            runningCuSeqlen += blockSeqLen;
378	            cuSeqlensData[cuSeqlensSize++] = static_cast<int32_t>(runningCuSeqlen);
379	        }
380	        maxSeqLen = std::max(maxSeqLen, blockSeqLen);
381	    }
382	}
383	
384	std::tuple<int64_t, int64_t> QwenViTRunner::getResizedImageSize(
385	    int64_t const /*numFrames*/, int64_t const height, int64_t const width, int64_t const maxRatio)
386	{
387	    // According to https://github.com/QwenLM/Qwen2-VL/blob/main/qwen-vl-utils/src/qwen_vl_utils/vision_process.py
388	    int64_t const factor = mConfig.patchSize * mConfig.mergeSize;
389	    int64_t const minPixels = mConfig.minImageTokensPerImage * factor * factor;
390	    int64_t const maxPixels = mConfig.maxImageTokensPerImage * factor * factor;
391	
392	    // Banker's rounding (round-half-to-even) to match Python's round() used by the HF reference.
393	    auto roundByFactor = [](int64_t value, int64_t factor) -> int64_t {
394	        int64_t q = value / factor;
395	        int64_t r = value - q * factor;
396	        int64_t twoR = 2 * r;
397	        if (twoR > factor || (twoR == factor && (q & 1)))
398	            ++q;
399	        return q * factor;
400	    };
401	    auto floorByFactor = [](int64_t value, int64_t factor) -> int64_t {
402	        return std::floor(static_cast<double>(value) / factor) * factor;
403	    };
404	    auto ceilByFactor = [](int64_t value, int64_t factor) -> int64_t {
405	        return std::ceil(static_cast<double>(value) / factor) * factor;
406	    };
407	
408	    ELLM_CHECK(std::max(height, width) / std::min(height, width) <= maxRatio,
409	        "absolute aspect ratio must be smaller than " + std::to_string(maxRatio) + ", got "
410	            + std::to_string(std::max(height, width) / std::min(height, width)));
411	
412	    int64_t hBar = std::max(factor, roundByFactor(height, factor));
413	    int64_t wBar = std::max(factor, roundByFactor(width, factor));
414	
415	    if (hBar * wBar > maxPixels)
416	    {
417	        double beta = std::sqrt(static_cast<double>(height * width) / maxPixels);
418	        // Clamp to >= factor: a heavily-downscaled image must not yield a sub-factor (or zero) dimension.
419	        hBar = std::max(factor, floorByFactor(static_cast<int64_t>(height / beta), factor));
420	        wBar = std::max(factor, floorByFactor(static_cast<int64_t>(width / beta), factor));

