432	void QwenViTRunner::imagePreprocess(
433	    rt::LLMGenerationRequest const& request, std::vector<VisionSpan>& spans, bool doResize, cudaStream_t stream)
434	{
435	    // Marshal each buffer's frames into the ViT scratch and append its spans. totalSeqLength doubles as the running
436	    // patch offset threaded across buffers, so after the loop it is the total ViT patch count.
437	    int64_t totalSeqLength = 0;
438	    int64_t imageCount = 0;
439	    for (auto const& req : request.requests)
440	    {
441	        for (auto const& image : req.imageBuffers)
442	        {
443	            if (doResize)
444	            {
445	                auto [resizedHeight, resizedWidth] = getResizedImageSize(image.frames, image.height, image.width);
446	                rt::imageUtils::resizeImage(
447	                    image, mResizedImageHost, resizedWidth, resizedHeight, rt::imageUtils::InterpolationMode::kBICUBIC);
448	                formatPatch(mResizedImageHost, spans, totalSeqLength, stream);
449	            }
450	            else
451	            {
452	                formatPatch(image, spans, totalSeqLength, stream);
453	            }
454	            ++imageCount;
455	        }
456	    }
457	
458	    if (totalSeqLength == 0)
459	    {
460	        check::check(mVitInput.reshape({totalSeqLength, mConfig.inputDim}), "Tensor reshape failed");
461	        return;
462	    }
463	
464	    ELLM_CHECK(totalSeqLength >= mConfig.minHW && totalSeqLength <= mConfig.maxHW,
465	        "totalSeqLength " + std::to_string(totalSeqLength) + " exceeds the limitation, max = "
466	            + std::to_string(mConfig.maxHW) + ", min = " + std::to_string(mConfig.minHW) + " of VIT engine.");
467	
468	    // Reshape tensors
469	    int64_t totalImageTokens = totalSeqLength / (mConfig.mergeSize * mConfig.mergeSize);
470	    check::check(mVitInput.reshape({totalSeqLength, mConfig.inputDim}), "Tensor reshape failed");
471	    check::check(mOutputEmbedding.reshape({totalImageTokens, mConfig.outHiddenSize}), "Tensor reshape failed");
472	    // Record performance data
473	    mMultimodalMetrics.recordRun(imageCount, totalImageTokens);
474	
475	    /*
476	     * Cache optimization for cu_seqlens, rotary position embeddings, and other image grid dependent
477	     * input tensors. Reuse the data from last round of computation if the image grid sizes are identical.
478	     * This reduces inference latency by skipping invariant tensor initialization.
479	     */
480	    bool const vitGeometryUnchanged = spans.size() == mLastSpans.size()
481	        && std::equal(spans.begin(), spans.end(), mLastSpans.begin(),
482	            [](VisionSpan const& a, VisionSpan const& b) { return a.vit == b.vit; });
483	    if (!vitGeometryUnchanged)
484	    {
485	        // Build cu_seqlens + per-frame maxSeqLen
486	        int32_t* cuSeqlensData = mCuSeqlensHost.dataPointer<int32_t>();
487	        int64_t cuSeqlensSize = 1;
488	        int64_t maxSeqLen = 0;
489	        buildCuSeqlens(spans, cuSeqlensData, cuSeqlensSize, maxSeqLen);
490	        check::check(mCuSeqlens.reshape({cuSeqlensSize}), "Tensor reshape failed");
491	        CUDA_CHECK(cudaMemcpyAsync(mCuSeqlens.rawPointer(), mCuSeqlensHost.rawPointer(),
492	            cuSeqlensSize * sizeof(int32_t), cudaMemcpyHostToDevice, stream));
493	
494	        if (mUseTrtNativeVitAttn)
495	        {
496	            check::check(mKvLengths.reshape({cuSeqlensSize}), "Tensor reshape failed");
497	            CUDA_CHECK(cudaMemcpyAsync(mKvLengths.rawPointer(), mCuSeqlensHost.rawPointer(),
498	                cuSeqlensSize * sizeof(int32_t), cudaMemcpyHostToDevice, stream));
499	        }
500	
501	        if (mHasMaxSeqLenCarrier)
502	        {
503	            check::check(mMaxSeqLenCarrier.reshape({maxSeqLen}), "Tensor reshape failed");
504	        }
505	
506	        // Build rotary position embeddings
507	        check::check(mRotaryPosEmb.reshape({totalSeqLength, mConfig.vitPosEmbDim}), "Tensor reshape failed");
508	        for (auto const& s : spans)
509	        {
510	            kernel::initRotaryPosEmbQwenViT(mRotaryPosEmb, {s.vit.gridT, s.vit.gridH, s.vit.gridW}, mConfig.mergeSize,
511	                s.vit.patchStart, 10000.0f, 1.0f, stream);
512	        }
513	
514	        // Build model-specific ViT inputs.
515	        buildExtraInputs(spans, totalSeqLength, totalImageTokens, stream);
516	
517	        mLastSpans = spans;
518	    }
519	}
