521	void QwenViTRunner::getMRopePositionIds(
522	    std::vector<std::vector<int32_t>> const& batchInputIds, std::vector<VisionSpan> const& spans) noexcept
523	{
524	    // Mirrors HF Qwen2VLModel.get_rope_index (base = Qwen2-VL; also serves Qwen3-VL, whose sub-spans are llmGridT==1).
525	    // Temporal step is 1 (HF t_index = arange(grid_t)); span advance is spatial max(llmGridH, llmGridW).
526	
527	    // mropePositionIds: (bs, 3, maxPositionEmbeddings), 3 is for T, H, W
528	    int64_t* mropePositionIdsPtr = mMropePositionIdsHost.dataPointer<int64_t>();
529	    int64_t const maxPositionEmbeddings = mMropePositionIdsHost.getShape()[2];
530	    int64_t totalImageIdx = 0;
531	    int64_t batchOffset = 0;
532	
533	    mMropeRopeDeltasPerBatch.clear();
534	    for (auto const& inputIds : batchInputIds)
535	    {
536	        auto start = inputIds.begin();
537	        auto end = inputIds.end();
538	        auto it = inputIds.begin();
539	        int64_t startIdx = 0;
540	        int64_t remainingStartPos = 0;
541	
542	        while ((it = std::find(start, end, mConfig.visionStartTokenId)) != end)
543	        {
544	            // Text part
545	            int64_t textLen = it + 1 - start;
546	            for (int64_t i = 0; i < 3; ++i)
547	            {
548	                for (int64_t j = 0; j < textLen; ++j)
549	                {
550	                    mropePositionIdsPtr[batchOffset + i * maxPositionEmbeddings + remainingStartPos + j] = j + startIdx;
551	                }
552	            }
553	
554	            // Visual part — the Nth <|vision_start|> consumes the Nth span (global order). MRoPE reads the LLM view.
555	            LlmVisionBlock const& block = spans[totalImageIdx].llm;
556	            int64_t const llmGridT = block.llmGridT;
557	            int64_t const llmGridH = block.llmGridH;
558	            int64_t const llmGridW = block.llmGridW;
559	            ++totalImageIdx;
560	
561	            for (int64_t t = 0; t < llmGridT; ++t)
562	            {
563	                for (int64_t h = 0; h < llmGridH; ++h)
564	                {
565	                    for (int64_t w = 0; w < llmGridW; ++w)
566	                    {
567	                        int64_t idx = remainingStartPos + textLen + t * llmGridH * llmGridW + h * llmGridW + w;
568	                        mropePositionIdsPtr[batchOffset + 0 * maxPositionEmbeddings + idx] = t + textLen + startIdx;
569	                        mropePositionIdsPtr[batchOffset + 1 * maxPositionEmbeddings + idx] = h + textLen + startIdx;
570	                        mropePositionIdsPtr[batchOffset + 2 * maxPositionEmbeddings + idx] = w + textLen + startIdx;
571	                    }
572	                }
573	            }
574	
575	            start = it + 1 + llmGridT * llmGridH * llmGridW;
576	            startIdx += std::max(llmGridH, llmGridW) + textLen; // spatial-only advance (T not counted)
577	            remainingStartPos = start - inputIds.begin();
578	        }
579	
580	        // MRoPE rope delta for this batch: maxMropePositionId + 1 - inputIdSize
581	        int64_t const maxMropePositionId = startIdx + inputIds.size() - remainingStartPos - 1;
582	        mMropeRopeDeltasPerBatch.push_back(maxMropePositionId + 1 - inputIds.size());
583	
584	        // Remaining text part till maxPositionEmbeddings. Treat all generated tokens as text tokens.
585	        int64_t textLen = maxPositionEmbeddings - remainingStartPos;
586	        for (int64_t i = 0; i < 3; ++i)
587	        {
588	            for (int64_t j = 0; j < textLen; ++j)
589	            {
590	                mropePositionIdsPtr[batchOffset + i * maxPositionEmbeddings + remainingStartPos + j] = j + startIdx;
591	            }
592	        }
593	
594	        batchOffset += 3 * maxPositionEmbeddings;
595	    }
596	}
