598	void QwenViTRunner::generateMropeParams(std::vector<std::vector<int32_t>> const& batchInputIds,
599	    std::vector<VisionSpan> const& spans, rt::Tensor& ropeRotaryCosSinDevice, cudaStream_t stream)
600	{
601	    int64_t const activeBatchSize = batchInputIds.size();
602	    auto ropeRotaryCosSinDim = ropeRotaryCosSinDevice.getShape();
603	    int64_t const maxPositionEmbeddings = ropeRotaryCosSinDim[1];
604	    int64_t const rotaryDim = ropeRotaryCosSinDim[2];
605	
606	    bool checkShapeValid = activeBatchSize <= mLLMMaxBatchSize && maxPositionEmbeddings <= mLLMMaxSequenceLength;
607	    if (!checkShapeValid)
608	    {
609	        LOG_ERROR(
610	            "mropePositionIdsHost shape is not valid. Allowed shape: [%d, 3, %d]. "
611	            "Got activeBatchSize: %d, maxPositionEmbeddings: %ld",
612	            mLLMMaxBatchSize, mLLMMaxSequenceLength, activeBatchSize, maxPositionEmbeddings);
613	        throw std::runtime_error("mropePositionIdsHost shape validation failed");
614	    }
615	
616	    // Initialize mropePositionIds and copy to device
617	    check::check(mMropePositionIdsHost.reshape({activeBatchSize, 3, maxPositionEmbeddings}), "Tensor reshape failed");
618	    check::check(mMropePositionIdsDevice.reshape({activeBatchSize, 3, maxPositionEmbeddings}), "Tensor reshape failed");
619	    getMRopePositionIds(batchInputIds, spans);
620	    CUDA_CHECK(cudaMemcpyAsync(mMropePositionIdsDevice.rawPointer(), mMropePositionIdsHost.rawPointer(),
621	        activeBatchSize * 3 * maxPositionEmbeddings * sizeof(int64_t), cudaMemcpyHostToDevice, stream));
622	
623	    // Initialize mrope cosSinCacheDevice
624	    check::check(
625	        ropeRotaryCosSinDevice.reshape({activeBatchSize, maxPositionEmbeddings, rotaryDim}), "Tensor reshape failed");
626	    bool interleaved = mConfig.mropeInterleaved;
627	    kernel::initializeMRopeCosSin(ropeRotaryCosSinDevice.dataPointer<float>(),
628	        mMropePositionIdsDevice.dataPointer<int64_t>(), mConfig.mropeTheta, rotaryDim, maxPositionEmbeddings,
629	        activeBatchSize, interleaved, mConfig.mropeSectionH, mConfig.mropeSectionW, stream);
630	}
