632	void QwenViTRunner::textPreprocess(rt::LLMGenerationRequest const& request,
633	    std::vector<std::vector<int32_t>>& batchInputIds, std::vector<VisionSpan> const& spans,
634	    trt_edgellm::tokenizer::Tokenizer const* tokenizer)
635	{
636	    // Flat visual-pad expansion: each vision pad (<|image_pad|>/<|video_pad|>) -> its span's numTokens incrementing
637	    // IDs (>= vocabSize), consumed by embeddingLookupWithImageInsertion.
638	    int32_t nextImageTokenId = mConfig.vocabSize;
639	    size_t spanIdx = 0;
640	
641	    for (size_t i = 0; i < request.requests.size(); ++i)
642	    {
643	        // Reuse tokens if another runner already tokenized this request, else tokenize it now.
644	        std::vector<int32_t> ids;
645	        if (i < batchInputIds.size() && !batchInputIds[i].empty())
646	        {
647	            ids = batchInputIds[i];
648	        }
649	        else
650	        {
651	            ids = tokenizer->encode(request.formattedRequests[i].formattedCompleteRequest);
652	        }
653	
654	        std::vector<int32_t> newIds;
655	        for (size_t j = 0; j < ids.size(); ++j)
656	        {
657	            if (ids[j] == mConfig.imageTokenId || ids[j] == mConfig.videoTokenId)
658	            {
659	                ELLM_CHECK(spanIdx < spans.size(),
660	                    "Pad token found but no matching vision span at index " + std::to_string(spanIdx));
661	                LlmVisionBlock const& block = spans[spanIdx++].llm;
662	                for (int64_t k = 0; k < block.numTokens; ++k)
663	                {
664	                    newIds.push_back(nextImageTokenId++);
665	                }
666	            }
667	            else
668	            {
669	                newIds.push_back(ids[j]);
670	            }
671	        }
672	
673	        if (i < batchInputIds.size())
674	        {
675	            batchInputIds[i] = std::move(newIds);
676	        }
677	        else
678	        {
679	            batchInputIds.emplace_back(std::move(newIds));
680	        }
681	    }
682	}
