684	bool QwenViTRunner::preprocess(rt::LLMGenerationRequest const& request,
685	    std::vector<std::vector<int32_t>>& batchedInputIds, tokenizer::Tokenizer const* tokenizer,
686	    rt::OptionalOutputTensor mropeCosSinOut, cudaStream_t stream, bool imageOnly)
687	{
688	    std::vector<VisionSpan> spans; // per-request vision layout; lives only across this call
689	
690	    try
691	    {
692	        imagePreprocess(request, spans, !imageOnly, stream);
693	        if (!imageOnly)
694	        {
695	            if (!mropeCosSinOut.has_value())
696	            {
697	                LOG_ERROR("mropeCosSinOut is required when imageOnly=false.");
698	                return false;
699	            }
700	            textPreprocess(request, batchedInputIds, spans, tokenizer);
701	            generateMropeParams(batchedInputIds, spans, mropeCosSinOut.value().get(), stream);
702	        }
703	    }
704	    catch (std::exception const& e)
705	    {
706	        LOG_ERROR("Failed: %s", e.what());
707	        return false;
708	    }
709	
710	    return true;
711	}
