714	    rt::OptionalOutputTensor mropeCosSinOut, cudaStream_t stream)
715	{
716	    if (systemPrompt.empty())
717	    {
718	        return true;
719	    }
720	
721	    if (!mropeCosSinOut.has_value())
722	    {
723	        LOG_ERROR("mropeCosSinOut is required for non-empty system prompts.");
724	        return false;
725	    }
726	
727	    // systemPrompt is already formatted by tokenizer's applyChatTemplate
728	    std::vector<int32_t> ids = tokenizer->encode(systemPrompt);
729	    if (ids.empty())
730	    {
731	        LOG_ERROR("Failed to encode system prompt.");
732	        return false;
733	    }
734	    std::vector<std::vector<int32_t>> batchedInputIds;
735	    batchedInputIds.emplace_back(std::move(ids));
736	
737	    try
738	    {
