750	bool QwenViTRunner::infer(cudaStream_t stream) noexcept
751	{
752	    // Skip VIT inference if there are no images to process
753	    // Check if the first dimension (sequence length) is 0, indicating no images
754	    if (mVitInput.getShape()[0] == 0)
755	    {
756	        return true;
757	    }
758	
759	    // Profile ViT inference with automatic cleanup
760	    {
761	        TIME_STAGE(metrics::StageNames::kVISION_ENCODER, stream);
762	
763	        bool setEngineIOStatus{true};
764	        setEngineIOStatus
765	            &= mVisualContext->setInputShape(binding_names::kVisualInput, mVitInput.getShape().getTRTDims());
766	        setEngineIOStatus
767	            &= mVisualContext->setInputShape(binding_names::kRotaryPosEmb, mRotaryPosEmb.getShape().getTRTDims());
768	        setEngineIOStatus
769	            &= mVisualContext->setInputShape(binding_names::kCuSeqlens, mCuSeqlens.getShape().getTRTDims());
770	        if (mUseTrtNativeVitAttn)
771	        {
772	            setEngineIOStatus
773	                &= mVisualContext->setInputShape(binding_names::kKvLengths, mKvLengths.getShape().getTRTDims());
774	        }
775	        if (mHasMaxSeqLenCarrier)
776	        {
777	            setEngineIOStatus &= mVisualContext->setInputShape(
778	                binding_names::kMaxSeqLenCarrier, mMaxSeqLenCarrier.getShape().getTRTDims());
779	        }
780	        // Model-specific ViT-input shapes (window vs fast-pos-emb); base adds none.
781	        setEngineIOStatus &= bindExtraInputShapes();
782	
783	        if (!setEngineIOStatus)
784	        {
785	            LOG_ERROR("Failed to bind engine input tensors.");
786	            return false;
787	        }
788	
789	        bool enqueueStatus = mVisualContext->enqueueV3(stream);
790	        if (!enqueueStatus)
791	        {
792	            LOG_ERROR("Failed to enqueue engine.");
793	            return false;
794	        }
795	    }
796	
797	    return true;
798	}
